import java.io.InputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public boolean hasNext() {
            while (hasNextByte() && buffer[ptr] <= ' ') {
                ptr++;
            }
            return hasNextByte();
        }

        public int nextInt() {
            if (!hasNext()) throw new RuntimeException("No more tokens");
            int c = readByte();
            int res = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') {
                    throw new NumberFormatException();
                }
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res;
        }
    }

    static class FenwickTree {
        int n;
        long[] tree;

        FenwickTree(int n) {
            this.n = n;
            this.tree = new long[n + 2];
        }

        void add(int i, long delta) {
            for (; i <= n; i += i & -i) {
                tree[i] += delta;
            }
        }

        void rangeAdd(int l, int r, long delta) {
            if (l > r) return;
            add(l, delta);
            if (r + 1 <= n) {
                add(r + 1, -delta);
            }
        }

        long query(int i) {
            long sum = 0;
            for (; i > 0; i -= i & -i) {
                sum += tree[i];
            }
            return sum;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        if (!scanner.hasNext()) return;

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        FenwickTree bitA = new FenwickTree(n);
        FenwickTree bitB = new FenwickTree(n);

        StringBuilder sb = new StringBuilder();

        for (int q = 0; q < m; q++) {
            int type = scanner.nextInt();
            if (type == 1) {
                int i = scanner.nextInt();
                long v = scanner.nextInt();
                int l = i;
                int r = (int) Math.min((long) n, i + v - 1);
                long a = -1;
                long b = v + i;
                bitA.rangeAdd(l, r, a);
                bitB.rangeAdd(l, r, b);
            } else if (type == 2) {
                int i = scanner.nextInt();
                long v = scanner.nextInt();
                int l = (int) Math.max(1L, i - v + 1);
                int r = i;
                long a = 1;
                long b = v - i;
                bitA.rangeAdd(l, r, a);
                bitB.rangeAdd(l, r, b);
            } else {
                int i = scanner.nextInt();
                long totalA = bitA.query(i);
                long totalB = bitB.query(i);
                long ans = totalA * i + totalB;
                sb.append(ans).append('\n');
            }
        }

        System.out.print(sb.toString());
    }
}
